// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address sender) public {
        amount = bound(amount, 0, address(this).balance + 1e30);
        Reverter bad = new Reverter();

        vm.deal(address(c), amount);

        vm.prank(address(this));
        bool ok;
        try c.sendMoney(address(bad), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("bad");
    }
}
